--
-- Name: bom_version_supersede_previous(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bom_version_supersede_previous() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'APPROVED' AND NEW.effective_to IS NULL
       AND (TG_OP = 'INSERT'
            OR OLD.status <> 'APPROVED'
            OR OLD.effective_to IS NOT NULL) THEN
        UPDATE bom_versions
        SET status       = 'OBSOLETE',
            effective_to = COALESCE(NEW.effective_from, CURRENT_DATE) - INTERVAL '1 day',
            updated_at   = NOW()
        WHERE bom_recipe_id = NEW.bom_recipe_id
          AND id           <> NEW.id
          AND status        = 'APPROVED'
          AND effective_to IS NULL
          AND deleted_at   IS NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION bom_version_supersede_previous(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bom_version_supersede_previous() IS 'M-BOM-VER-1 auto-supersede: new APPROVED version → OBSOLETE prior APPROVED for same bom_recipe_id. Issue #724: BEFORE trigger so OBSOLETE precedes partial-unique-index check on the NEW row.';


--
-- Name: fn_maintain_lineage_closure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_maintain_lineage_closure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- 1. Self-ref source (depth 0)
    INSERT INTO batch_lineage_closure
        (id, factory_id, ancestor_type, ancestor_id, descendant_type, descendant_id, depth, created_at, updated_at)
    VALUES
        (gen_random_uuid()::VARCHAR, NEW.factory_id, NEW.source_type, NEW.source_id,
         NEW.source_type, NEW.source_id, 0, NOW(), NOW())
    ON CONFLICT (factory_id, ancestor_id, ancestor_type, descendant_id, descendant_type) DO NOTHING;

    -- 2. Self-ref target (depth 0)
    INSERT INTO batch_lineage_closure
        (id, factory_id, ancestor_type, ancestor_id, descendant_type, descendant_id, depth, created_at, updated_at)
    VALUES
        (gen_random_uuid()::VARCHAR, NEW.factory_id, NEW.target_type, NEW.target_id,
         NEW.target_type, NEW.target_id, 0, NOW(), NOW())
    ON CONFLICT (factory_id, ancestor_id, ancestor_type, descendant_id, descendant_type) DO NOTHING;

    -- 3. Direct edge (depth 1)
    INSERT INTO batch_lineage_closure
        (id, factory_id, ancestor_type, ancestor_id, descendant_type, descendant_id, depth, created_at, updated_at)
    VALUES
        (gen_random_uuid()::VARCHAR, NEW.factory_id, NEW.source_type, NEW.source_id,
         NEW.target_type, NEW.target_id, 1, NOW(), NOW())
    ON CONFLICT (factory_id, ancestor_id, ancestor_type, descendant_id, descendant_type) DO NOTHING;

    -- 4. All ancestors of source become ancestors of target at depth+1
    INSERT INTO batch_lineage_closure
        (id, factory_id, ancestor_type, ancestor_id, descendant_type, descendant_id, depth, created_at, updated_at)
    SELECT gen_random_uuid()::VARCHAR, NEW.factory_id, anc.ancestor_type, anc.ancestor_id,
           NEW.target_type, NEW.target_id, anc.depth + 1, NOW(), NOW()
    FROM batch_lineage_closure anc
    WHERE anc.factory_id = NEW.factory_id
      AND anc.descendant_id = NEW.source_id
      AND anc.descendant_type = NEW.source_type
      AND anc.depth > 0
    ON CONFLICT (factory_id, ancestor_id, ancestor_type, descendant_id, descendant_type) DO NOTHING;

    -- 5. Source becomes ancestor of all existing descendants of target at depth+1
    INSERT INTO batch_lineage_closure
        (id, factory_id, ancestor_type, ancestor_id, descendant_type, descendant_id, depth, created_at, updated_at)
    SELECT gen_random_uuid()::VARCHAR, NEW.factory_id, NEW.source_type, NEW.source_id,
           desc_.descendant_type, desc_.descendant_id, desc_.depth + 1, NOW(), NOW()
    FROM batch_lineage_closure desc_
    WHERE desc_.factory_id = NEW.factory_id
      AND desc_.ancestor_id = NEW.target_id
      AND desc_.ancestor_type = NEW.target_type
      AND desc_.depth > 0
    ON CONFLICT (factory_id, ancestor_id, ancestor_type, descendant_id, descendant_type) DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: lock_product_process_workflow_activation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_product_process_workflow_activation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  lock_factory_id VARCHAR(64);
  lock_product_type_id VARCHAR(64);
BEGIN
  IF TG_OP = 'DELETE' THEN
    lock_factory_id := OLD.factory_id;
    lock_product_type_id := OLD.product_type_id;
  ELSE
    lock_factory_id := NEW.factory_id;
    lock_product_type_id := NEW.product_type_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    lock_factory_id || E'\\x1f' || lock_product_type_id,
    0
  ));

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: lock_workflow_production_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_workflow_production_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  lock_product_type_id VARCHAR(64);
  active_reference_count BIGINT;
  enters_running BOOLEAN := FALSE;
BEGIN
  IF TG_TABLE_NAME = 'product_process_workflow_activations' THEN
    IF TG_OP = 'UPDATE'
       AND OLD.enabled IS TRUE
       AND NEW.enabled IS FALSE THEN
      lock_product_type_id := NEW.product_type_id;
      PERFORM pg_advisory_xact_lock(hashtextextended(
        CAST(NEW.factory_id AS text) || E'\\x1f' || CAST(lock_product_type_id AS text),
        0
      ));

      SELECT COUNT(*)
        INTO active_reference_count
        FROM (
          SELECT 1
            FROM public.production_plans plan
           WHERE plan.factory_id = NEW.factory_id
             AND plan.selected_workflow_id = NEW.active_workflow_id
             AND plan.deleted_at IS NULL
             AND plan.status IN ('IN_PROGRESS', 'PRODUCING', 'PAUSED')
          UNION ALL
          SELECT 1
            FROM public.production_batches batch
           WHERE batch.factory_id = NEW.factory_id
             AND batch.selected_workflow_id = NEW.active_workflow_id
             AND batch.deleted_at IS NULL
             AND batch.status IN ('IN_PROGRESS', 'PRODUCING', 'PAUSED')
        ) references_in_use;

      IF active_reference_count > 0 THEN
        RAISE EXCEPTION
          'Workflow % still has % running production references; deactivate rejected after recheck',
          NEW.active_workflow_id, active_reference_count
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.selected_workflow_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Joint-output rows may carry an output SKU different from the Workflow owner.
  SELECT workflow.product_type_id
    INTO lock_product_type_id
    FROM public.product_process_workflows workflow
   WHERE workflow.id = NEW.selected_workflow_id
     AND workflow.factory_id = NEW.factory_id
     AND workflow.definition_version = NEW.selected_workflow_version
   LIMIT 1;
  IF lock_product_type_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    enters_running := NEW.status IN ('IN_PROGRESS', 'PRODUCING', 'PAUSED');
  ELSE
    enters_running := NEW.status IN ('IN_PROGRESS', 'PRODUCING', 'PAUSED')
                      AND (OLD.status IS DISTINCT FROM NEW.status
                           OR OLD.selected_workflow_id IS DISTINCT FROM NEW.selected_workflow_id);
  END IF;
  IF enters_running THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      CAST(NEW.factory_id AS text) || E'\\x1f' || CAST(lock_product_type_id AS text),
      0
    ));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION lock_workflow_production_reference(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lock_workflow_production_reference() IS 'Serializes Workflow deactivation with running production plan/batch INSERT and status transitions.';


--
-- Name: pin_production_batch_workflow_selection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pin_production_batch_workflow_selection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  plan_mode VARCHAR(16);
  plan_workflow_id BIGINT;
  plan_workflow_version INTEGER;
  plan_workflow_revision_id BIGINT;
  plan_workflow_revision_hash VARCHAR(64);
  plan_bom_family_id VARCHAR(64);
  plan_bom_recipe_ids JSONB;
  plan_bom_versions JSONB;
  plan_output_units JSONB;
  plan_target_finished_good_ids JSONB;
  plan_found BOOLEAN := FALSE;
  governed_workflow_exists BOOLEAN := FALSE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(
    NEW.factory_id || E'\\x1f' || NEW.product_type_id,
    0
  ));

  IF NEW.production_plan_id IS NOT NULL THEN
    SELECT workflow_selection_mode,
           selected_workflow_id,
           selected_workflow_version,
           selected_workflow_revision_id,
           selected_workflow_revision_hash,
           selected_bom_family_id,
           selected_bom_recipe_ids_by_product,
           selected_bom_versions_by_product,
           workflow_output_units_by_product,
           target_finished_good_ids
      INTO plan_mode,
           plan_workflow_id,
           plan_workflow_version,
           plan_workflow_revision_id,
           plan_workflow_revision_hash,
           plan_bom_family_id,
           plan_bom_recipe_ids,
           plan_bom_versions,
           plan_output_units,
           plan_target_finished_good_ids
      FROM production_plans
     WHERE id = NEW.production_plan_id
       AND factory_id = NEW.factory_id;
    plan_found := FOUND;
    IF NOT plan_found THEN
      RAISE EXCEPTION
        'production batch plan % does not exist in factory %',
        NEW.production_plan_id, NEW.factory_id
        USING ERRCODE = '23503';
    END IF;
  END IF;

  IF plan_mode = 'WORKFLOW' THEN
    -- Expand-phase compatibility: while the old blue/green slot can still
    -- write during migration startup, copy its legacy Workflow selection
    -- without rejecting the batch. The new service always writes the complete
    -- authority below and fails incomplete plans closed at runtime. A later
    -- contract migration may enforce NOT NULL only after every writer has
    -- crossed this deployment boundary.
    NEW.workflow_selection_mode := 'WORKFLOW';
    NEW.selected_workflow_id := plan_workflow_id;
    NEW.selected_workflow_version := plan_workflow_version;
    NEW.selected_workflow_revision_id := plan_workflow_revision_id;
    NEW.selected_workflow_revision_hash := plan_workflow_revision_hash;
    NEW.selected_bom_family_id := plan_bom_family_id;
    NEW.selected_bom_recipe_ids_by_product := COALESCE(plan_bom_recipe_ids, '{}'::jsonb);
    NEW.selected_bom_versions_by_product := COALESCE(plan_bom_versions, '{}'::jsonb);
    NEW.workflow_output_units_by_product := COALESCE(plan_output_units, '{}'::jsonb);
    NEW.target_finished_good_ids := COALESCE(plan_target_finished_good_ids, '[]'::jsonb);
  ELSIF plan_mode = 'LEGACY' THEN
    RAISE EXCEPTION
      'production plan % is pinned to the retired LEGACY mode; only canvas-governed workflows can produce',
      NEW.production_plan_id
      USING ERRCODE = '23514';
  ELSIF NEW.production_plan_id IS NOT NULL THEN
    RAISE EXCEPTION
      'production plan % lacks an explicit workflow selection snapshot',
      NEW.production_plan_id
      USING ERRCODE = '23514';
  ELSE
    SELECT EXISTS (
      SELECT 1
        FROM product_process_workflow_activations activation
       WHERE activation.factory_id = NEW.factory_id
         AND activation.product_type_id = NEW.product_type_id
         AND activation.enabled = TRUE
         AND activation.deleted_at IS NULL
    )
      INTO governed_workflow_exists;
    IF governed_workflow_exists THEN
      RAISE EXCEPTION
        'product % in factory % is Workflow-governed; create the batch through a production plan',
        NEW.product_type_id, NEW.factory_id
        USING ERRCODE = '23514';
    END IF;
    RAISE EXCEPTION
      'product % in factory % has no published/enabled canvas workflow; LEGACY production was retired 2026-08-09',
      NEW.product_type_id, NEW.factory_id
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION pin_production_batch_workflow_selection(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pin_production_batch_workflow_selection() IS 'INSERT 时把生产计划的工艺/BOM 选择钉进批次。不挂计划的批次一律拒绝, 唯一例外是 batch_type=''CLERK_WIP'' 的逐道报工中间半成品批次 (V20261029_82) —— 它按设计不挂计划(避免成本重复计), 工艺权威在同计划的成品批次上。';


--
-- Name: set_sales_order_invoice_todo_on_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_sales_order_invoice_todo_on_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IS DISTINCT FROM 'COMPLETED'
       AND NEW.status = 'COMPLETED'
       AND NEW.invoice_todo_status IS NULL THEN
        NEW.invoice_todo_status := 'PENDING';
        NEW.invoice_todo_attempts := 0;
        NEW.invoice_todo_next_attempt_at := NULL;
        NEW.invoice_todo_last_error := NULL;
    END IF;
    RETURN NEW;
END;
$$;


