--
-- Name: accounting_periods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.accounting_periods (
    id character varying(191) NOT NULL,
    factory_id character varying(191) NOT NULL,
    year integer NOT NULL,
    month integer NOT NULL,
    status character varying(32) DEFAULT 'OPEN'::character varying NOT NULL,
    opened_at timestamp without time zone,
    opened_by bigint,
    closed_at timestamp without time zone,
    closed_by bigint,
    reopened_at timestamp without time zone,
    reopened_by bigint,
    reopen_reason character varying(1000),
    approval_workflow_instance_id character varying(191),
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    adjust_deadline timestamp without time zone,
    reconciliation_status character varying(32),
    reconciliation_summary character varying(2000),
    total_revenue_snapshot numeric(18,2),
    net_profit_snapshot numeric(18,2),
    income_statement_snapshot text,
    report_ready_at timestamp without time zone,
    closing_posted_at timestamp without time zone,
    CONSTRAINT accounting_periods_month_check CHECK (((month >= 1) AND (month <= 12))),
    CONSTRAINT accounting_periods_status_check CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'PENDING_CLOSE'::character varying, 'CLOSED'::character varying])::text[])))
);


--
-- Name: TABLE accounting_periods; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.accounting_periods IS 'Sprint 7 T2 F-PERIOD: 期间结账状态记录. factory_id 内 (year, month) 唯一. 没有 row 默认 OPEN.';


--
-- Name: COLUMN accounting_periods.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.status IS 'OPEN (默认, voucher 可写) | PENDING_CLOSE (财务发起, 走 BUDGET_APPROVAL workflow) | CLOSED (gate voucher 写)';


--
-- Name: COLUMN accounting_periods.reopen_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.reopen_reason IS '反结账原因 audit log — finance director CLOSED→OPEN 操作必填';


--
-- Name: COLUMN accounting_periods.approval_workflow_instance_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.approval_workflow_instance_id IS 'PENDING_CLOSE 时关联的 ApprovalWorkflowInstance.id (BUDGET_APPROVAL decisionType)';


--
-- Name: COLUMN accounting_periods.adjust_deadline; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.adjust_deadline IS 'Wave2 月结: 结账后调整窗口截止 (closed_at + 20 天). CLOSED 期间在此之前 voucher 仍可写; 之后硬锁. null = 旧 CLOSED 行立即硬锁 (backwards compat).';


--
-- Name: COLUMN accounting_periods.reconciliation_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.reconciliation_status IS 'Wave2 月结: 结账前对账校验结论. PASS (无阻塞) | WARNING (有未审批调整等非阻塞项) | null (未执行月结编排).';


--
-- Name: COLUMN accounting_periods.reconciliation_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.reconciliation_summary IS 'Wave2 月结: 对账校验摘要文本 (各 check 项汇总), 审计留痕.';


--
-- Name: COLUMN accounting_periods.total_revenue_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.total_revenue_snapshot IS 'Wave2 月结: 结账时冻结的营业收入合计 (来自 IncomeStatement P&L).';


--
-- Name: COLUMN accounting_periods.net_profit_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.net_profit_snapshot IS 'Wave2 月结: 结账时冻结的净利润 (来自 IncomeStatement P&L).';


--
-- Name: COLUMN accounting_periods.income_statement_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.income_statement_snapshot IS 'Wave2 月结: 结账时冻结的完整利润表 JSON 快照. 调整窗口内 voucher 变动不影响此快照 (报表冻结).';


--
-- Name: COLUMN accounting_periods.report_ready_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.accounting_periods.report_ready_at IS 'Wave2 月结: 报表 (P&L 快照) 生成完成时间. 邓总 "1-3号出报表" 达成标记.';


