--
-- Name: annual_tax_settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.annual_tax_settlements (
    id character varying(36) DEFAULT (gen_random_uuid())::text NOT NULL,
    factory_id character varying(50) NOT NULL,
    user_id bigint NOT NULL,
    tax_year integer NOT NULL,
    total_salary numeric(14,2) DEFAULT 0 NOT NULL,
    total_bonus numeric(14,2) DEFAULT 0 NOT NULL,
    total_social_insurance numeric(14,2) DEFAULT 0 NOT NULL,
    total_provident_fund numeric(14,2) DEFAULT 0 NOT NULL,
    total_special_deductions numeric(14,2) DEFAULT 0 NOT NULL,
    annual_taxable_income numeric(14,2) DEFAULT 0 NOT NULL,
    annual_tax_due numeric(14,2) DEFAULT 0 NOT NULL,
    monthly_prepaid_sum numeric(14,2) DEFAULT 0 NOT NULL,
    refund_owed numeric(14,2) DEFAULT 0 NOT NULL,
    annual_bonus_tax numeric(14,2) DEFAULT 0 NOT NULL,
    bracket_label character varying(20),
    bracket_rate character varying(10),
    status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    months_covered integer DEFAULT 0 NOT NULL,
    computed_at timestamp without time zone DEFAULT now(),
    confirmed_at timestamp without time zone,
    confirmed_by bigint,
    reported_at timestamp without time zone,
    reported_by bigint,
    notes character varying(500),
    created_at timestamp without time zone DEFAULT now(),
    updated_at timestamp without time zone DEFAULT now(),
    deleted_at timestamp without time zone,
    CONSTRAINT ck_annual_tax_due_nonneg CHECK ((annual_tax_due >= (0)::numeric)),
    CONSTRAINT ck_annual_tax_months CHECK (((months_covered >= 0) AND (months_covered <= 12))),
    CONSTRAINT ck_annual_tax_total_salary_nonneg CHECK ((total_salary >= (0)::numeric)),
    CONSTRAINT ck_annual_tax_year_range CHECK (((tax_year >= 2000) AND (tax_year <= 2100)))
);


--
-- Name: TABLE annual_tax_settlements; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.annual_tax_settlements IS '#833 follow-up — 年度汇算 (China 综合所得 annual settlement). UNIQUE (factory, user, tax_year) WHERE deleted_at IS NULL. State: DRAFT → CONFIRMED → REPORTED.';


--
-- Name: COLUMN annual_tax_settlements.refund_owed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.annual_tax_settlements.refund_owed IS '汇算补退 = annual_tax_due − monthly_prepaid_sum. >0: 应补缴, <0: 应退税, =0: 平账';


--
-- Name: COLUMN annual_tax_settlements.annual_bonus_tax; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.annual_tax_settlements.annual_bonus_tax IS '年终奖个税 (info-only, sum of #861 annual_bonus_tax). 一次性年终奖独立计税, 不进汇算';


--
-- Name: COLUMN annual_tax_settlements.months_covered; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.annual_tax_settlements.months_covered IS '实际参与汇算的月数 (≤12). 跨年入职或离职时 < 12';


