);


--
-- Name: ar_ap_transactions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ar_ap_transactions (
    id character varying(191) NOT NULL,
    factory_id character varying(191) NOT NULL,
    transaction_number character varying(50) NOT NULL,
    transaction_type character varying(32) NOT NULL,
    counterparty_type character varying(32) NOT NULL,
    counterparty_id character varying(191) NOT NULL,
    counterparty_name character varying(200),
    sales_order_id character varying(191),
    purchase_order_id character varying(191),
    pos_order_sync_id bigint,
    amount numeric(15,2) NOT NULL,
    balance_after numeric(15,2) NOT NULL,
    payment_method character varying(32),
    payment_reference character varying(100),
    transaction_date date NOT NULL,
    due_date date,
    operated_by bigint,
    remark character varying(500),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp without time zone,
    approval_status character varying(32) DEFAULT 'APPROVED'::character varying NOT NULL,
    approved_by bigint,
    approved_at timestamp without time zone,
    source_type character varying(50),
    source_id character varying(191),
    settled_amount numeric(15,2),
    outstanding_amount numeric(15,2),
    payment_status character varying(32),
    currency_code character varying(3),
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ck_aat_cp_type CHECK (((counterparty_type)::text = ANY (ARRAY[('CUSTOMER'::character varying)::text, ('SUPPLIER'::character varying)::text]))),
    CONSTRAINT ck_aat_pay_method CHECK (((payment_method IS NULL) OR ((payment_method)::text = ANY (ARRAY[('CASH'::character varying)::text, ('BANK_TRANSFER'::character varying)::text, ('WECHAT'::character varying)::text, ('ALIPAY'::character varying)::text, ('CHECK'::character varying)::text, ('CREDIT'::character varying)::text, ('POS'::character varying)::text, ('OTHER'::character varying)::text])))),
    CONSTRAINT ck_aat_pending_only_adjustment CHECK ((((approval_status)::text = ANY ((ARRAY['APPROVED'::character varying, 'PENDING'::character varying, 'REJECTED'::character varying])::text[])) AND (((approval_status)::text <> 'PENDING'::text) OR ((transaction_type)::text = ANY ((ARRAY['AR_ADJUSTMENT'::character varying, 'AP_ADJUSTMENT'::character varying])::text[]))))),
    CONSTRAINT ck_aat_type CHECK (((transaction_type)::text = ANY ((ARRAY['AR_INVOICE'::character varying, 'AR_PAYMENT'::character varying, 'AR_ADJUSTMENT'::character varying, 'AR_CREDIT_NOTE'::character varying, 'AP_INVOICE'::character varying, 'AP_PAYMENT'::character varying, 'AP_ADJUSTMENT'::character varying, 'AP_CREDIT_NOTE'::character varying])::text[]))),
    CONSTRAINT ck_ar_ap_currency_code CHECK (((currency_code IS NULL) OR ((currency_code)::text ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT ck_ar_ap_open_item CHECK ((((transaction_type)::text <> ALL ((ARRAY['AP_INVOICE'::character varying, 'AR_INVOICE'::character varying])::text[])) OR (amount IS NULL) OR (((payment_status)::text = 'NEEDS_RECONCILIATION'::text) AND (settled_amount IS NULL) AND (outstanding_amount IS NULL)) OR ((settled_amount IS NOT NULL) AND (outstanding_amount IS NOT NULL) AND (settled_amount >= (0)::numeric) AND (outstanding_amount >= (0)::numeric) AND ((settled_amount + outstanding_amount) = abs(amount)) AND ((payment_status)::text = ANY ((ARRAY['UNPAID'::character varying, 'PARTIALLY_PAID'::character varying, 'PAID'::character varying])::text[])) AND ((((payment_status)::text = 'UNPAID'::text) AND (settled_amount = (0)::numeric) AND (outstanding_amount > (0)::numeric)) OR (((payment_status)::text = 'PARTIALLY_PAID'::text) AND (settled_amount > (0)::numeric) AND (outstanding_amount > (0)::numeric)) OR (((payment_status)::text = 'PAID'::text) AND (outstanding_amount = (0)::numeric))))))
);


--
-- Name: async_task_failures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.async_task_failures (
    id bigint NOT NULL,
    dedup_key character varying(255) NOT NULL,
    factory_id character varying(50),
    method_signature character varying(255) NOT NULL,
    business_key character varying(191),
    exception_class character varying(255) NOT NULL,
    exception_message text,
    stack_excerpt text,
    remediation_hint text,
    status character varying(20) DEFAULT 'OPEN'::character varying NOT NULL,
    occurrence_count integer DEFAULT 1 NOT NULL,
    first_seen_at timestamp without time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp without time zone DEFAULT now() NOT NULL,
    resolved_at timestamp without time zone,
    resolved_by character varying(100),
    resolve_note text,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_async_task_failure_count CHECK ((occurrence_count >= 1)),
    CONSTRAINT chk_async_task_failure_status CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'RESOLVED'::character varying])::text[])))
);


--
-- Name: TABLE async_task_failures; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.async_task_failures IS '@Async void 方法逃逸异常的台账。只收【已登记】的方法(见 AsyncFailureEnrollment), 未登记的仍然只打日志 —— 宁可窄而可信, 不要宽到被人忽略。';


--
-- Name: COLUMN async_task_failures.dedup_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.async_task_failures.dedup_key IS 'methodSignature|factoryId|businessKey|exceptionClass, 空值写 ''-''。超 255 字符会被截断 —— 截断后两条不同的失败理论上可能并成一条, 这是已知的代理判据局限。';


--
-- Name: COLUMN async_task_failures.factory_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.async_task_failures.factory_id IS 'NULL = 提取器判不出工厂, 不是「没有工厂」。异步线程不带 MDC 上下文, 只能从事件参数取。';


--
-- Name: COLUMN async_task_failures.occurrence_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.async_task_failures.occurrence_count IS '跨 resolve 周期累加。已 RESOLVED 的失败再次发生会被重新置回 OPEN —— 复发是新消息。';


--
-- Name: async_task_failures_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.async_task_failures_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: async_task_failures_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.async_task_failures_id_seq OWNED BY public.async_task_failures.id;


--
-- Name: attachments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attachments (
    id character varying(191) NOT NULL,
    factory_id character varying(50) NOT NULL,
    entity_type character varying(50) NOT NULL,
    entity_id character varying(191) NOT NULL,
    file_name character varying(255) NOT NULL,
    file_url character varying(1000) NOT NULL,
    thumbnail_url character varying(1000),
    file_size bigint NOT NULL,
    file_type character varying(50) NOT NULL,
    file_category character varying(32) DEFAULT 'OTHER'::character varying NOT NULL,
    file_storage character varying(20) DEFAULT 'OSS'::character varying NOT NULL,
    file_hash character varying(64),
    business_tag character varying(50),
    description character varying(500),
    uploaded_by bigint NOT NULL,
    uploaded_at timestamp without time zone DEFAULT now() NOT NULL,
    upload_source character varying(20) DEFAULT 'WEB'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    CONSTRAINT chk_att_category CHECK (((file_category)::text = ANY ((ARRAY['PHOTO'::character varying, 'VIDEO'::character varying, 'DOCUMENT'::character varying, 'VOUCHER'::character varying, 'SIGNATURE'::character varying, 'CONTRACT'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT chk_att_entity_type CHECK (((entity_type)::text = ANY (ARRAY['CUSTOMER'::text, 'CUSTOMER_TRACKING'::text, 'PURCHASE_ORDER'::text, 'PURCHASE_RECEIPT'::text, 'CUSTOMER_SUPPLIED_RECEIPT'::text, 'QUALITY_CHECK'::text, 'PRODUCTION_BATCH'::text, 'PAYMENT_VOUCHER'::text, 'INVOICE'::text, 'RD_SAMPLE'::text, 'RECEIPT'::text, 'RETURN_ORDER'::text, 'SHIPMENT'::text, 'WASTAGE_RECORD'::text, 'GROUP_LEADER_REPORT'::text, 'EXPENSE_REPORT'::text, 'LEAVE_REQUEST'::text, 'TIMECLOCK_PHOTO'::text, 'SALES_ORDER'::text, 'INVENTORY'::text, 'ECN'::text, 'CALL_RECORD'::text, 'PRODUCTION_REPORT'::text, 'GENERIC'::text]))),
    CONSTRAINT chk_att_size_positive CHECK ((file_size > 0)),
    CONSTRAINT chk_att_storage CHECK (((file_storage)::text = ANY ((ARRAY['OSS'::character varying, 'R2'::character varying, 'LOCAL'::character varying])::text[])))
);


--
-- Name: TABLE attachments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.attachments IS '通用附件表 (多态: entity_type + entity_id) — C-ATT-1';


--
-- Name: COLUMN attachments.entity_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.entity_type IS '关联实体类型, 白名单约束 (CHECK chk_att_entity_type) 与 Java Attachment.EntityType 枚举同步. 加 PRODUCTION_REPORT 用于单次报工照片/视频证据.';


--
-- Name: COLUMN attachments.file_category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.file_category IS '文件分类: PHOTO/VIDEO/DOCUMENT/VOUCHER/SIGNATURE/CONTRACT/OTHER. 跟 Java FileCategory enum 同步. CONTRACT 是 Sprint 5 H-1 新加, 用于 SalesOrderListDTO linkCounts 区分 文件/图片/合同 三类 (HJ link_type 对齐).';


--
-- Name: COLUMN attachments.file_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.file_hash IS 'SHA256 客户端计算, 同 factory 同 hash 视为同一文件 (register 时触发去重)';


--
-- Name: COLUMN attachments.uploaded_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.attachments.uploaded_by IS '上传者 user.id; 软删除时校验 uploaded_by = current user OR admin';


--
-- Name: CONSTRAINT chk_att_entity_type ON attachments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT chk_att_entity_type ON public.attachments IS '与 Attachment.EntityType 全量对齐 (补 CUSTOMER_SUPPLIED_RECEIPT)。改枚举必须同步改这里, EnumCheckConstraintDriftTest 会挡。';


