--
-- Name: bom_item_substitutes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bom_item_substitutes (
    id character varying(64) NOT NULL,
    factory_id character varying(50) NOT NULL,
    recipe_id character varying(191) NOT NULL,
    parent_kind character varying(24) NOT NULL,
    parent_recipe_item_id bigint,
    parent_seasoning_item_id bigint,
    parent_material_type_id_snapshot character varying(191) NOT NULL,
    parent_material_name_snapshot character varying(200) NOT NULL,
    material_category_snapshot character varying(32) NOT NULL,
    work_process_id_snapshot character varying(50),
    workflow_process_node_id_snapshot character varying(128),
    packaging_spec_id_snapshot character varying(36),
    packaging_role_snapshot character varying(64),
    substitute_material_type_id character varying(191) NOT NULL,
    substitute_material_code_snapshot character varying(50),
    substitute_material_name_snapshot character varying(200) NOT NULL,
    parent_unit_snapshot character varying(20) NOT NULL,
    substitute_unit_snapshot character varying(20) NOT NULL,
    conversion_factor numeric(24,12) NOT NULL,
    conversion_explicit boolean DEFAULT false NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    CONSTRAINT chk_bis_conversion_factor CHECK ((conversion_factor > (0)::numeric)),
    CONSTRAINT chk_bis_material_category CHECK (((material_category_snapshot)::text = ANY ((ARRAY['RAW'::character varying, 'AUXILIARY'::character varying, 'PACKAGING'::character varying])::text[]))),
    CONSTRAINT chk_bis_not_self CHECK (((parent_material_type_id_snapshot)::text <> (substitute_material_type_id)::text)),
    CONSTRAINT chk_bis_packaging_role CHECK ((((material_category_snapshot)::text <> 'PACKAGING'::text) OR (packaging_role_snapshot IS NOT NULL))),
    CONSTRAINT chk_bis_parent_identity CHECK (((((parent_kind)::text = 'RECIPE_ITEM'::text) AND (parent_recipe_item_id IS NOT NULL) AND (parent_seasoning_item_id IS NULL)) OR (((parent_kind)::text = 'SEASONING_ITEM'::text) AND (parent_recipe_item_id IS NULL) AND (parent_seasoning_item_id IS NOT NULL)))),
    CONSTRAINT chk_bis_parent_kind CHECK (((parent_kind)::text = ANY ((ARRAY['RECIPE_ITEM'::character varying, 'SEASONING_ITEM'::character varying])::text[]))),
    CONSTRAINT chk_bis_parent_scope CHECK (((((parent_kind)::text = 'SEASONING_ITEM'::text) AND ((material_category_snapshot)::text = 'AUXILIARY'::text) AND (work_process_id_snapshot IS NOT NULL) AND (workflow_process_node_id_snapshot IS NOT NULL)) OR (((parent_kind)::text = 'RECIPE_ITEM'::text) AND ((material_category_snapshot)::text = ANY ((ARRAY['RAW'::character varying, 'PACKAGING'::character varying])::text[])))))
);


--
-- Name: TABLE bom_item_substitutes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bom_item_substitutes IS 'Version-local structured BOM parent-to-substitute rules; no migration from legacy free-text groups.';


--
-- Name: COLUMN bom_item_substitutes.conversion_factor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_item_substitutes.conversion_factor IS 'Substitute quantity equivalent to one parent requirement quantity; actual consumption remains batch truth.';


