-- Name: bom_recipe_item_cost_corrections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bom_recipe_item_cost_corrections (
    id character varying(191) NOT NULL,
    factory_id character varying(50) NOT NULL,
    bom_recipe_id character varying(191) NOT NULL,
    bom_recipe_item_id bigint NOT NULL,
    material_type_id character varying(191) NOT NULL,
    old_unit_price numeric(15,4),
    new_unit_price numeric(15,4) NOT NULL,
    old_item_cost numeric(15,4),
    new_item_cost numeric(15,4) NOT NULL,
    reason character varying(255) NOT NULL,
    corrected_by bigint NOT NULL,
    corrected_by_role character varying(50) NOT NULL,
    corrected_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_bricc_changed CHECK (((old_unit_price IS DISTINCT FROM new_unit_price) OR (old_item_cost IS DISTINCT FROM new_item_cost))),
    CONSTRAINT chk_bricc_nonnegative_cost CHECK ((new_item_cost >= (0)::numeric)),
    CONSTRAINT chk_bricc_positive_price CHECK ((new_unit_price > (0)::numeric))
);


--
-- Name: bom_recipe_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bom_recipe_items (
    id bigint NOT NULL,
    recipe_id character varying(191) NOT NULL,
    factory_id character varying(50) NOT NULL,
    material_type_id character varying(191),
    material_name character varying(200),
    standard_quantity numeric(15,4),
    yield_rate numeric(6,2) DEFAULT 100.00 NOT NULL,
    actual_quantity numeric(15,4),
    unit character varying(20) NOT NULL,
    unit_price numeric(15,4),
    tax_rate numeric(5,2) DEFAULT 0,
    item_cost numeric(15,4),
    material_category character varying(32) DEFAULT 'RAW'::character varying NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    is_optional boolean DEFAULT false NOT NULL,
    substitute_group character varying(50),
    remark character varying(500),
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    per_portion boolean DEFAULT false NOT NULL,
    semi_finished_ref_code character varying(100),
    primary_code_ref character varying(3),
    sub_product_type_id character varying(100),
    primary_code character varying(3),
    price_unit character varying(20),
    quantity_to_price_factor numeric(24,12) DEFAULT 1 NOT NULL,
    packaging_spec_id character varying(36),
    packaging_spec_name_snapshot character varying(100),
    packaging_role character varying(64),
    natural_quantity numeric(15,6),
    natural_unit character varying(20),
    packaging_package_unit_snapshot character varying(20),
    packaging_base_unit_snapshot character varying(20),
    packaging_conversion_factor_snapshot numeric(20,8),
    workflow_material_node_id character varying(128),
    workflow_input_port_id character varying(128),
    workflow_edge_id character varying(128),
    cost_scope character varying(24),
    cost_scope_key character varying(1024),
    CONSTRAINT chk_bri_category CHECK (((material_category)::text = ANY ((ARRAY['RAW'::character varying, 'AUXILIARY'::character varying, 'PACKAGING'::character varying, 'BYPRODUCT'::character varying, 'SEMI_FINISHED'::character varying])::text[]))),
    CONSTRAINT chk_bri_material_ref_xor CHECK (((material_type_id IS NOT NULL) <> (semi_finished_ref_code IS NOT NULL))),
    CONSTRAINT chk_bri_qty CHECK (((standard_quantity IS NULL) OR (standard_quantity > (0)::numeric))),
    CONSTRAINT chk_bri_yield CHECK (((yield_rate > (0)::numeric) AND (yield_rate <= (100)::numeric))),
    CONSTRAINT ck_bri_cost_scope CHECK (((cost_scope IS NULL) OR ((cost_scope)::text = ANY ((ARRAY['SHARED'::character varying, 'OUTPUT_GROUP'::character varying, 'OUTPUT_EXCLUSIVE'::character varying])::text[])))),
    CONSTRAINT ck_bri_cost_scope_key CHECK ((((cost_scope)::text <> 'OUTPUT_GROUP'::text) OR (NULLIF(btrim((cost_scope_key)::text), ''::text) IS NOT NULL)))
);


--
-- Name: TABLE bom_recipe_items; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bom_recipe_items IS 'M-BOM-1 BOM 配方项. 硬外键 raw_material_types — 禁手写物料名称 (客户原话 May10 line 217-222).';


--
-- Name: COLUMN bom_recipe_items.material_type_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.material_type_id IS '原料档案外键 raw_material_types.id; 半成品(回料)行为 NULL, 身份改由 semi_finished_ref_code 承担 (chk_bri_material_ref_xor 保证恰有一个非空)';


--
-- Name: COLUMN bom_recipe_items.unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.unit IS 'Canonical unit code resolved by UnitContractService; legacy localized values remain supported';


--
-- Name: COLUMN bom_recipe_items.material_category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.material_category IS 'RAW / AUXILIARY / PACKAGING / SEMI_FINISHED = 投入; BYPRODUCT = 产出的副产声明(SKU + 预计产出量), 不计入成本池';


--
-- Name: COLUMN bom_recipe_items.per_portion; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.per_portion IS 'SP4: true = 每份用量, false = 按批次总量 (默认)';


--
-- Name: COLUMN bom_recipe_items.semi_finished_ref_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.semi_finished_ref_code IS '半成品(回料)引用编码 = semi_finished_inventory.intermediate_batch_no; 非空即代表本行是半成品行, 此时 material_type_id 必须为 NULL';


--
-- Name: COLUMN bom_recipe_items.primary_code_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.primary_code_ref IS 'SP8: 物料前三位主编码冗余列; BOM按类型搜索/统计用; 与 material_type_id 不替代';


--
-- Name: COLUMN bom_recipe_items.sub_product_type_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.sub_product_type_id IS 'SP1: 子产品类型ID (关联 product_types.id)。非 null 时触发嵌套 BOM 成本递归聚合。null = 普通原材料行 (用 unit_price)。配合 semi_finished_ref_code 支持"先做后用"移动均价优先。';


--
-- Name: COLUMN bom_recipe_items.primary_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.primary_code IS 'SP8: BOM item material primary code copied from raw_material_types.primary_code; nullable for historical rows';


--
-- Name: COLUMN bom_recipe_items.packaging_spec_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.packaging_spec_id IS 'null=SKU base selling level; non-null=ProductPackagingSpec snapshot identity';


--
-- Name: COLUMN bom_recipe_items.natural_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.natural_quantity IS 'Natural quantity at the selected packaging level; standard_quantity remains base-unit equivalent';


--
-- Name: COLUMN bom_recipe_items.workflow_input_port_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bom_recipe_items.workflow_input_port_id IS 'Stable Workflow input port represented by this BOM material rule';


--
