--
-- Name: bom_recipes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bom_recipes (
    id character varying(191) NOT NULL,
    factory_id character varying(50) NOT NULL,
    recipe_code character varying(50) NOT NULL,
    product_type_id character varying(50) NOT NULL,
    product_name character varying(200) NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    is_current boolean DEFAULT true NOT NULL,
    overall_yield_rate numeric(6,2),
    output_quantity_per_unit numeric(15,4) NOT NULL,
    output_unit character varying(20) DEFAULT 'g'::character varying NOT NULL,
    total_material_cost numeric(15,4),
    total_labor_cost numeric(15,4),
    total_overhead_cost numeric(15,4),
    total_cost numeric(15,4),
    standard_sale_price numeric(15,2),
    status character varying(32) DEFAULT 'DRAFT'::character varying NOT NULL,
    activated_at timestamp without time zone,
    activated_by bigint,
    source_type character varying(20) DEFAULT 'MANUAL'::character varying NOT NULL,
    source_sample_id character varying(191),
    notes character varying(500),
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    seasoning_revision bigint DEFAULT 0 NOT NULL,
    net_content_quantity numeric(15,6),
    net_content_unit character varying(20),
    workflow_revision_id bigint,
    workflow_id bigint,
    workflow_definition_version integer,
    workflow_revision_hash character varying(64),
    workflow_schema_version integer,
    workflow_nodes_snapshot_json jsonb,
    workflow_edges_snapshot_json jsonb,
    bom_family_id character varying(64),
    shared_recipe_id character varying(191),
    target_terminal_node_id character varying(128),
    output_role character varying(24),
    cost_allocation_ratio numeric(7,4),
    byproduct_nrv_unit_price numeric(15,4),
    CONSTRAINT chk_br_output CHECK ((output_quantity_per_unit > (0)::numeric)),
    CONSTRAINT chk_br_source CHECK (((source_type)::text = ANY ((ARRAY['MANUAL'::character varying, 'SAMPLE_AUTOGEN'::character varying, 'AI_GENERATED'::character varying, 'IMPORTED'::character varying])::text[]))),
    CONSTRAINT chk_br_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'ACTIVE'::character varying, 'ARCHIVED'::character varying])::text[]))),
    CONSTRAINT chk_br_yield CHECK (((overall_yield_rate IS NULL) OR ((overall_yield_rate > (0)::numeric) AND (overall_yield_rate <= (300)::numeric)))),
    CONSTRAINT ck_br_byproduct_nrv_unit_price CHECK (((byproduct_nrv_unit_price IS NULL) OR (byproduct_nrv_unit_price > (0)::numeric))),
    CONSTRAINT ck_br_cost_allocation_ratio CHECK (((cost_allocation_ratio IS NULL) OR ((cost_allocation_ratio >= (0)::numeric) AND (cost_allocation_ratio <= (100)::numeric)))),
    CONSTRAINT ck_br_output_role CHECK (((output_role IS NULL) OR ((output_role)::text = ANY ((ARRAY['MAIN'::character varying, 'CO_PRODUCT'::character varying, 'BY_PRODUCT'::character varying])::text[]))))
);


