--

CREATE TABLE public.customer_material_arrival_notices (
    id character varying(64) NOT NULL,
    factory_id character varying(191) NOT NULL,
    notice_number character varying(50) NOT NULL,
    customer_id character varying(191),
    expected_arrival_at timestamp without time zone,
    contact_name character varying(100),
    contact_phone character varying(50),
    remark character varying(1000),
    status character varying(32) DEFAULT 'PENDING_APPROVAL'::character varying NOT NULL,
    receipt_count integer DEFAULT 0 NOT NULL,
    last_received_at timestamp without time zone,
    created_by bigint NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    inbound_reason character varying(32) DEFAULT 'CUSTOMER_MATERIAL'::character varying NOT NULL,
    reviewed_by bigint,
    reviewed_at timestamp without time zone,
    review_remark character varying(1000),
    CONSTRAINT chk_cman_customer_requirement CHECK ((((inbound_reason)::text <> 'CUSTOMER_MATERIAL'::text) OR (customer_id IS NOT NULL))),
    CONSTRAINT chk_cman_inbound_reason CHECK (((inbound_reason)::text = ANY ((ARRAY['CUSTOMER_MATERIAL'::character varying, 'GIFT'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT chk_cman_receipt_count CHECK ((receipt_count >= 0)),
    CONSTRAINT chk_cman_status CHECK (((status)::text = ANY ((ARRAY['PENDING_APPROVAL'::character varying, 'OPEN'::character varying, 'PARTIALLY_RECEIVED'::character varying, 'RECEIVED'::character varying, 'REJECTED'::character varying, 'CANCELLED'::character varying])::text[])))
);


--
-- Name: TABLE customer_material_arrival_notices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.customer_material_arrival_notices IS 'Operations-created non-order inbound request; inventory is written only by warehouse receipt';


--
-- Name: COLUMN customer_material_arrival_notices.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_material_arrival_notices.status IS 'PENDING_APPROVAL/REJECTED/CANCELLED remain application-only; OPEN and later statuses are warehouse receiving tasks';


--
-- Name: COLUMN customer_material_arrival_notices.inbound_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_material_arrival_notices.inbound_reason IS 'CUSTOMER_MATERIAL creates customer-owned inventory; GIFT and OTHER create company-owned inventory';


--
-- Name: COLUMN customer_material_arrival_notices.reviewed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_material_arrival_notices.reviewed_by IS 'Warehouse reviewer user id; null until approved or rejected';


