    CONSTRAINT customers_credit_period_days_check CHECK (((credit_period_days IS NULL) OR ((credit_period_days >= 0) AND (credit_period_days <= 365)))),
    CONSTRAINT customers_credit_status_check CHECK (((credit_status)::text = ANY ((ARRAY['NORMAL'::character varying, 'WARNING'::character varying, 'SUSPENDED'::character varying])::text[])))
);


