-- Name: finished_goods_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.finished_goods_batches (
    id character varying(191) NOT NULL,
    factory_id character varying(191) NOT NULL,
    batch_number character varying(64) NOT NULL,
    product_type_id character varying(191) NOT NULL,
    product_name character varying(200),
    produced_quantity numeric(15,4) NOT NULL,
    shipped_quantity numeric(15,4) DEFAULT 0 NOT NULL,
    reserved_quantity numeric(15,4) DEFAULT 0 NOT NULL,
    unit character varying(20) NOT NULL,
    unit_price numeric(15,4),
    production_date date,
    expire_date date,
    storage_location character varying(100),
    production_plan_id character varying(191),
    status character varying(32) DEFAULT 'AVAILABLE'::character varying NOT NULL,
    created_by bigint,
    remark text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp without time zone,
    version bigint DEFAULT 0,
    warehouse_id character varying(64) NOT NULL,
    reversal_log_id bigint,
    nominal_quantity numeric(15,4),
    counterparty_confirmed boolean,
    inbound_remark text,
    unit_cost numeric(15,4),
    packaging_spec_id character varying(36),
    packaging_spec_name character varying(60),
    packaging_unit character varying(20),
    packaging_base_unit character varying(20),
    packaging_factor numeric(20,8),
    ownership character varying(32),
    owner_customer_id character varying(191),
    source_sales_order_id character varying(191),
    source_sales_order_item_id character varying(191),
    CONSTRAINT chk_finished_goods_owner_consistency CHECK ((((ownership IS NULL) AND (owner_customer_id IS NULL)) OR (((ownership)::text = 'COMPANY_OWNED'::text) AND (owner_customer_id IS NULL)) OR (((ownership)::text = 'CUSTOMER_OWNED'::text) AND (owner_customer_id IS NOT NULL)))),
    CONSTRAINT chk_finished_goods_ownership CHECK (((ownership IS NULL) OR ((ownership)::text = ANY ((ARRAY['COMPANY_OWNED'::character varying, 'CUSTOMER_OWNED'::character varying])::text[]))))
);


--
-- Name: COLUMN finished_goods_batches.warehouse_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finished_goods_batches.warehouse_id IS 'FK to factory_warehouses.id. 客户 D1 双仓流转 (2026-05-10 spec). 默认 WH-WKS.';


--
-- Name: COLUMN finished_goods_batches.reversal_log_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finished_goods_batches.reversal_log_id IS 'SP2撤回完成后关联 report_reversal_logs.id; NULL=未撤回';


--
-- Name: COLUMN finished_goods_batches.nominal_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finished_goods_batches.nominal_quantity IS '气调货标称数 (一托标36). null=非气调/无差异. 库存按 produced_quantity(实收)计量';


--
-- Name: COLUMN finished_goods_batches.counterparty_confirmed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finished_goods_batches.counterparty_confirmed IS '对方划单确认 (气调差异需对方签字). null=不适用';


--
-- Name: COLUMN finished_goods_batches.inbound_remark; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finished_goods_batches.inbound_remark IS '入库差异/划单备注 (留痕)';


--
-- Name: COLUMN finished_goods_batches.unit_cost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finished_goods_batches.unit_cost IS '成品单位成本 (小结成本传导写入; = (批次原料+调料+人工成本 + Σ SFI投料 feedKg×SFI.unit_cost) / 入库量); null = 成本未知(诚实null, 不伪造0)。区别于 unit_price(售价)';


--
-- Name: COLUMN finished_goods_batches.ownership; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finished_goods_batches.ownership IS 'COMPANY_OWNED or CUSTOMER_OWNED; NULL only for legacy/unknown lineage';


--
-- Name: COLUMN finished_goods_batches.owner_customer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.finished_goods_batches.owner_customer_id IS 'Opaque owning customer ID for CUSTOMER_OWNED finished goods';


--
