    employee_medical_rate numeric(6,4) DEFAULT 0.0200 NOT NULL,
    employer_medical_rate numeric(6,4) DEFAULT 0.0800 NOT NULL,
    employee_unemployment_rate numeric(6,4) DEFAULT 0.0050 NOT NULL,
    employer_unemployment_rate numeric(6,4) DEFAULT 0.0050 NOT NULL,
    employee_provident_fund_rate numeric(6,4) DEFAULT 0.0800 NOT NULL,
