    CONSTRAINT chk_insurance_rates_range CHECK ((((employee_pension_rate >= (0)::numeric) AND (employee_pension_rate <= 0.30)) AND ((employer_pension_rate >= (0)::numeric) AND (employer_pension_rate <= 0.30)) AND ((employee_medical_rate >= (0)::numeric) AND (employee_medical_rate <= 0.30)) AND ((employer_medical_rate >= (0)::numeric) AND (employer_medical_rate <= 0.30)) AND ((employee_unemployment_rate >= (0)::numeric) AND (employee_unemployment_rate <= 0.30)) AND ((employer_unemployment_rate >= (0)::numeric) AND (employer_unemployment_rate <= 0.30)) AND ((employee_provident_fund_rate >= (0)::numeric) AND (employee_provident_fund_rate <= 0.30)) AND ((employer_provident_fund_rate >= (0)::numeric) AND (employer_provident_fund_rate <= 0.30)))),
    CONSTRAINT chk_insurance_status CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'ARCHIVED'::character varying])::text[])))
);


