--
-- Name: intent_preview_tokens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.intent_preview_tokens (
    id bigint NOT NULL,
    token character varying(64) NOT NULL,
    factory_id character varying(50) NOT NULL,
    user_id bigint NOT NULL,
    username character varying(100),
    intent_code character varying(100) NOT NULL,
    intent_name character varying(200),
    entity_type character varying(50),
    entity_id character varying(100),
    operation character varying(20),
    preview_data text,
    current_values text,
    new_values text,
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    expires_at timestamp without time zone NOT NULL,
    resolved_at timestamp without time zone,
    resolution_message character varying(500),
    client_info character varying(200),
    tenant_id character varying(50),
    tool_name character varying(150),
    descriptor_version character varying(64),
    execution_mode character varying(20),
    parameters_hash character varying(64),
    command_digest character varying(64),
    claim_id character varying(64),
    claimed_at timestamp without time zone,
    CONSTRAINT ck_ipt_atomic_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'EXECUTING'::character varying, 'CONFIRMED'::character varying, 'FAILED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[]))),
    CONSTRAINT ck_ipt_digest_lengths CHECK ((((parameters_hash IS NULL) OR (length((parameters_hash)::text) = 64)) AND ((command_digest IS NULL) OR (length((command_digest)::text) = 64)))),
    CONSTRAINT ck_ipt_executing_claim CHECK ((((status)::text <> 'EXECUTING'::text) OR ((claim_id IS NOT NULL) AND (claimed_at IS NOT NULL) AND (tenant_id IS NOT NULL) AND (tool_name IS NOT NULL) AND (descriptor_version IS NOT NULL) AND ((execution_mode)::text = 'EXECUTE'::text) AND (parameters_hash IS NOT NULL) AND (command_digest IS NOT NULL)))),
    CONSTRAINT ck_ipt_execution_mode CHECK (((execution_mode IS NULL) OR ((execution_mode)::text = ANY ((ARRAY['PREVIEW'::character varying, 'EXECUTE'::character varying])::text[]))))
);


