--
-- Name: label_qc_annotations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.label_qc_annotations (
    id character varying(36) NOT NULL,
    factory_id character varying(50) NOT NULL,
    task_id character varying(36) NOT NULL,
    photo_id character varying(36) NOT NULL,
    source character varying(10) NOT NULL,
    ai_candidate_id character varying(100),
    ai_label character varying(40),
    ai_confidence double precision,
    ai_evidence character varying(500),
    human_label character varying(40),
    x_min double precision,
    y_min double precision,
    x_max double precision,
    y_max double precision,
    reviewer_notes character varying(500),
    reviewed_by bigint,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp without time zone,
    row_version bigint DEFAULT 0 NOT NULL,
    audience character varying(10) DEFAULT 'CUSTOMER'::character varying NOT NULL,
    reviewed_at timestamp without time zone,
    CONSTRAINT chk_label_qc_annotation_ai_label CHECK (((ai_label IS NULL) OR ((ai_label)::text = ANY ((ARRAY['MISSING_WHITE_LABEL'::character varying, 'MISSING_COLOR_LABEL'::character varying, 'NO_DEFECT'::character varying, 'UNJUDGEABLE'::character varying])::text[])))),
    CONSTRAINT chk_label_qc_annotation_audience CHECK (((audience)::text = ANY ((ARRAY['CUSTOMER'::character varying, 'PLATFORM'::character varying])::text[]))),
    CONSTRAINT chk_label_qc_annotation_bbox CHECK ((((x_min IS NULL) AND (y_min IS NULL) AND (x_max IS NULL) AND (y_max IS NULL)) OR ((x_min >= (0)::double precision) AND (y_min >= (0)::double precision) AND (x_max <= (1)::double precision) AND (y_max <= (1)::double precision) AND (x_min < x_max) AND (y_min < y_max)))),
    CONSTRAINT chk_label_qc_annotation_confidence CHECK (((ai_confidence IS NULL) OR ((ai_confidence >= (0)::double precision) AND (ai_confidence <= (1)::double precision)))),
    CONSTRAINT chk_label_qc_annotation_human_label CHECK (((human_label IS NULL) OR ((human_label)::text = ANY ((ARRAY['MISSING_WHITE_LABEL'::character varying, 'MISSING_COLOR_LABEL'::character varying, 'NO_DEFECT'::character varying, 'UNJUDGEABLE'::character varying])::text[])))),
    CONSTRAINT chk_label_qc_annotation_source CHECK (((source)::text = ANY ((ARRAY['AI'::character varying, 'HUMAN'::character varying])::text[])))
);


--
-- Name: COLUMN label_qc_annotations.row_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.label_qc_annotations.row_version IS 'Optimistic lock used by independent platform diagnostic review.';


--
-- Name: COLUMN label_qc_annotations.audience; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.label_qc_annotations.audience IS 'CUSTOMER means actionable factory QC risk; PLATFORM means model/geometry diagnostic only.';


