--
-- Name: label_qc_tray_crops; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.label_qc_tray_crops (
    id character varying(36) NOT NULL,
    row_version bigint DEFAULT 0 NOT NULL,
    factory_id character varying(50) NOT NULL,
    task_id character varying(36) NOT NULL,
    photo_id character varying(36) NOT NULL,
    source_attachment_id character varying(191) NOT NULL,
    source_image_sha256 character varying(64),
    tray_index integer NOT NULL,
    ai_tray_key character varying(100),
    source_decision character varying(20) NOT NULL,
    tray_x_min double precision NOT NULL,
    tray_y_min double precision NOT NULL,
    tray_x_max double precision NOT NULL,
    tray_y_max double precision NOT NULL,
    crop_x_min double precision NOT NULL,
    crop_y_min double precision NOT NULL,
    crop_x_max double precision NOT NULL,
    crop_y_max double precision NOT NULL,
    padding_ratio double precision NOT NULL,
    crop_algorithm_version character varying(40) NOT NULL,
    object_review_sha256 character varying(64) NOT NULL,
    crop_spec_sha256 character varying(64) NOT NULL,
    coordinate_transform text NOT NULL,
    factory_label_proposals text NOT NULL,
    status character varying(20) NOT NULL,
    platform_review_detail text,
    reviewed_by bigint,
    reviewed_at timestamp without time zone,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp without time zone,
    CONSTRAINT chk_label_qc_tray_crop_bounds CHECK (((tray_x_min >= (0)::double precision) AND (tray_y_min >= (0)::double precision) AND (tray_x_max <= (1)::double precision) AND (tray_y_max <= (1)::double precision) AND (tray_x_min < tray_x_max) AND (tray_y_min < tray_y_max) AND (crop_x_min >= (0)::double precision) AND (crop_y_min >= (0)::double precision) AND (crop_x_max <= (1)::double precision) AND (crop_y_max <= (1)::double precision) AND (crop_x_min < crop_x_max) AND (crop_y_min < crop_y_max))),
    CONSTRAINT chk_label_qc_tray_crop_decision CHECK (((source_decision)::text = ANY ((ARRAY['CONFIRMED'::character varying, 'CORRECTED'::character varying, 'ADDED'::character varying])::text[]))),
    CONSTRAINT chk_label_qc_tray_crop_status CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'REVIEWED'::character varying, 'UNJUDGEABLE'::character varying])::text[])))
);


