    CONSTRAINT ck_ldo_pieces CHECK ((pieces >= 0)),
    CONSTRAINT ck_ldo_status CHECK (((status)::text = ANY ((ARRAY['IMPORTED'::character varying, 'PLANNED'::character varying, 'CONFIRMED'::character varying, 'CANCELLED'::character varying])::text[]))),
