    CONSTRAINT ck_lp_status CHECK (((status)::text = ANY ((ARRAY['DRAFT'::character varying, 'NEEDS_ACTION'::character varying, 'CONFIRMED'::character varying, 'EXPORTED'::character varying, 'CANCELLED'::character varying])::text[]))),
    CONSTRAINT ck_lp_target CHECK (((target_load_pct > (0)::numeric) AND (target_load_pct <= (100)::numeric)))
);


--
-- Name: COLUMN logistics_plans.optimize_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.logistics_plans.optimize_by IS '排线优化模式: TIME=时间最快(高德strategy=0) / DISTANCE=路程最短(strategy=2, 默认); regenerate复用本值';


