--
-- Name: COLUMN material_batch_date_corrections.field_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batch_date_corrections.field_name IS 'DTO 属性名。CHECK 白名单限定, 当前只有 receiptDate —— 扩它之前先确认那一列的可空性。';


--
-- Name: COLUMN material_batch_date_corrections.old_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batch_date_corrections.old_value IS 'NULL = 原来这一格就是空的, 不是「没记下来」。';


--
-- Name: COLUMN material_batch_date_corrections.corrected_by_role; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batch_date_corrections.corrected_by_role IS '更正当时的 JWT 角色码。角色事后会变, 只存 user_id 答不了「他当时凭什么能改」。';


--
-- Name: material_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.material_batches (
    id character varying(191) NOT NULL,
    created_at timestamp without time zone NOT NULL,
    deleted_at timestamp without time zone,
    updated_at timestamp without time zone NOT NULL,
    batch_number character varying(64) NOT NULL,
    created_by bigint NOT NULL,
    expire_date date,
    factory_id character varying(255) NOT NULL,
    last_used_at timestamp without time zone,
    material_type_id character varying(255),
    notes text,
    production_date date,
    purchase_date date,
    quality_certificate character varying(100),
    quantity_unit character varying(20) NOT NULL,
    inbound_date date NOT NULL,
    receipt_quantity numeric(18,6) NOT NULL,
    reserved_quantity numeric(18,6) NOT NULL,
    status character varying(255) NOT NULL,
    storage_location character varying(100),
    supplier_id character varying(255),
    unit_price numeric(10,2),
    used_quantity numeric(18,6) NOT NULL,
    weight_per_unit numeric(10,3),
    custom_fields jsonb DEFAULT '{}'::jsonb,
    version bigint DEFAULT 0 NOT NULL,
    inbound_type character varying(30),
    source_doc_type character varying(32),
    source_doc_id character varying(64),
    warehouse_id character varying(64) NOT NULL,
    box_count integer,
    factory_number character varying(100),
    origin_place character varying(200),
    ownership character varying(32),
    owner_customer_id character varying(191),
    source_sales_order_id character varying(191),
    source_sales_order_item_id character varying(191),
    source_event_key character varying(64),
    product_type_id character varying(191),
    byproduct_source_report_id bigint,
    byproduct_unit_price numeric(15,4),
    byproduct_price_confirmed_at timestamp without time zone,
    byproduct_price_confirmed_by bigint,
    contract_number character varying(100),
    supplier_batch_number character varying(100),
    CONSTRAINT chk_material_batches_owner_consistency CHECK ((((ownership IS NULL) AND (owner_customer_id IS NULL)) OR (((ownership)::text = 'COMPANY_OWNED'::text) AND (owner_customer_id IS NULL)) OR (((ownership)::text = 'CUSTOMER_OWNED'::text) AND (owner_customer_id IS NOT NULL)))),
    CONSTRAINT chk_material_batches_ownership CHECK (((ownership IS NULL) OR ((ownership)::text = ANY ((ARRAY['COMPANY_OWNED'::character varying, 'CUSTOMER_OWNED'::character varying])::text[])))),
    CONSTRAINT ck_material_batch_no_overconsume CHECK (((COALESCE(used_quantity, (0)::numeric) + COALESCE(reserved_quantity, (0)::numeric)) <= receipt_quantity))
);


--
-- Name: COLUMN material_batches.custom_fields; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.custom_fields IS 'AI-configured custom material batch fields';


--
-- Name: COLUMN material_batches.source_doc_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.source_doc_type IS '发起单类型: PURCHASE_RECEIVE / MATERIAL_REQUISITION_RETURN / SALES_RETURN / MANUAL_ADJUST';


--
-- Name: COLUMN material_batches.source_doc_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.source_doc_id IS '发起单ID (对应类型的单据主键)';


--
-- Name: COLUMN material_batches.warehouse_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.warehouse_id IS 'FK to factory_warehouses.id. 客户 D1 双仓流转 (2026-05-10 spec). 默认 WH-LOG.';


--
-- Name: COLUMN material_batches.box_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.box_count IS '粗略统计用箱数, 不参与库存计算';


--
-- Name: COLUMN material_batches.factory_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.factory_number IS 'SP4-A4: 生产厂家编号，用于一物一码标签 (可空)';


--
-- Name: COLUMN material_batches.origin_place; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.origin_place IS 'SP4-A4: 产地，用于一物一码标签 (可空)';


--
-- Name: COLUMN material_batches.ownership; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.ownership IS 'COMPANY_OWNED or CUSTOMER_OWNED; NULL only for legacy/unknown lineage';


--
-- Name: COLUMN material_batches.owner_customer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.owner_customer_id IS 'Opaque owning customer ID for CUSTOMER_OWNED inventory; no cross-factory FK';


--
-- Name: COLUMN material_batches.source_sales_order_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.source_sales_order_id IS 'Opaque source sales-order snapshot; no cross-factory FK';


--
-- Name: COLUMN material_batches.source_sales_order_item_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.source_sales_order_item_id IS 'Opaque source sales-order-line snapshot; no cross-factory FK';


--
-- Name: COLUMN material_batches.byproduct_source_report_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.byproduct_source_report_id IS '副产来源报工 ID; 非 NULL 即表示这是一条副产批次';


--
-- Name: COLUMN material_batches.byproduct_unit_price; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.byproduct_unit_price IS '副产单价(元/单位), 盘点时确认; NULL = 未确认, 不参与抵扣且展示为「未抵扣」';


--
-- Name: COLUMN material_batches.byproduct_price_confirmed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.byproduct_price_confirmed_at IS '副产单价确认时间; 与单价一起判定是否已确认 —— 有价无时间 = BOM 带来的参考价, 不算确认';


--
-- Name: COLUMN material_batches.byproduct_price_confirmed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.byproduct_price_confirmed_by IS '确认副产单价的用户 ID';


--
-- Name: COLUMN material_batches.contract_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.contract_number IS '合同号 —— 从收货行带入, 供批次追溯';


--
-- Name: COLUMN material_batches.supplier_batch_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.material_batches.supplier_batch_number IS '供应商/客户批次号 —— 从收货行带入; batch_number 仍是系统生成的库存批次号';


