    CONSTRAINT chk_osh_to_stage CHECK (((to_stage)::text = ANY ((ARRAY['LEAD'::character varying, 'QUALIFIED'::character varying, 'DEMO'::character varying, 'PROPOSAL'::character varying, 'NEGOTIATE'::character varying, 'VERBAL'::character varying, 'CLOSED_WON'::character varying, 'CLOSED_LOST'::character varying])::text[])))
);


