-- Name: payment_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payment_requests (
    id character varying(191) NOT NULL,
    version integer,
    factory_id character varying(191) NOT NULL,
    request_number character varying(50) NOT NULL,
    purchase_order_id character varying(191),
    supplier_id character varying(191),
    status character varying(32) DEFAULT 'PENDING'::character varying NOT NULL,
    amount numeric(12,2) NOT NULL,
    payment_method character varying(50),
    bank_name character varying(100),
    bank_account character varying(100),
    remark text,
    created_by bigint NOT NULL,
    finance_reviewed_by bigint,
    finance_reviewed_at timestamp without time zone,
    finance_review_note text,
    approved_by bigint,
    approved_at timestamp without time zone,
    approve_note text,
    paid_by bigint,
    paid_at timestamp without time zone,
    arap_transaction_id character varying(191),
    reject_reason text,
    cancelled_at timestamp without time zone,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    workflow_instance_id character varying(191),
    purpose_code character varying(50),
    purpose_description text,
    payee_name character varying(200),
    due_date timestamp without time zone,
    submitted_by bigint,
    settlement_type character varying(32),
    source_type character varying(16) DEFAULT 'PURCHASE'::character varying NOT NULL,
    sales_order_id character varying(191),
    customer_id character varying(191),
    CONSTRAINT ck_pr_source_direction CHECK (((((source_type)::text = 'PURCHASE'::text) AND (purchase_order_id IS NOT NULL) AND (sales_order_id IS NULL)) OR (((source_type)::text = 'SALES'::text) AND (customer_id IS NOT NULL) AND (purchase_order_id IS NULL) AND (supplier_id IS NULL))))
);


