--
-- Name: payroll_records; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payroll_records (
    id bigint NOT NULL,
    created_at timestamp without time zone NOT NULL,
    deleted_at timestamp without time zone,
    updated_at timestamp without time zone NOT NULL,
    approved_at timestamp without time zone,
    approved_by bigint,
    average_efficiency numeric(8,2),
    base_salary numeric(12,2),
    bonus_amount numeric(12,2),
    deduction_amount numeric(12,2),
    efficiency_rating character varying(1),
    factory_id character varying(50) NOT NULL,
    notes text,
    overtime_hours numeric(8,2),
    overtime_wage numeric(12,2),
    paid_at timestamp without time zone,
    period_end date NOT NULL,
    period_start date NOT NULL,
    period_type character varying(20) NOT NULL,
    piece_rate_wage numeric(12,2),
    piece_rule_id bigint,
    status character varying(20) NOT NULL,
    total_piece_count integer,
    total_wage numeric(12,2),
    total_work_hours numeric(8,2),
    worker_id bigint NOT NULL,
    worker_name character varying(50) NOT NULL,
    vflag character varying(20) DEFAULT 'UNCREATED'::character varying NOT NULL,
    wage_mode character varying(20),
    hourly_wage numeric(12,2),
    hourly_rule_id bigint,
    previous_total_wage numeric(12,2),
    recalculated_at timestamp without time zone,
    recalculated_by bigint,
    recalc_count integer DEFAULT 0 NOT NULL,
    recalc_log text,
    CONSTRAINT chk_payroll_wage_mode CHECK (((wage_mode IS NULL) OR ((wage_mode)::text = ANY ((ARRAY['PIECE_RATE'::character varying, 'HOURLY'::character varying, 'MIXED'::character varying])::text[])))),
    CONSTRAINT chk_pr_vflag CHECK (((vflag)::text = ANY ((ARRAY['UNCREATED'::character varying, 'PENDING'::character varying, 'CREATED'::character varying, 'FAILED'::character varying])::text[])))
);


--
-- Name: COLUMN payroll_records.wage_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_records.wage_mode IS '本次计算采用的 WageMode (PIECE_RATE / HOURLY / MIXED); NULL = 收敛前生成的历史行';


--
-- Name: COLUMN payroll_records.hourly_wage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_records.hourly_wage IS '工时工资 (常规工时 × 时薪); PIECE_RATE 模式恒为 0';


--
-- Name: COLUMN payroll_records.previous_total_wage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_records.previous_total_wage IS '最近一次重算之前的 total_wage —— 与 total_wage 并排看即「变更前 / 变更后」';


--
-- Name: COLUMN payroll_records.recalc_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payroll_records.recalc_log IS '重算审计: 每次重算追加一行 [重算] 时间 by 操作人: 总额 旧 → 新 (差额)';


