--
-- Name: product_work_processes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_work_processes (
    id bigint NOT NULL,
    factory_id character varying(50) NOT NULL,
    product_type_id character varying(50) NOT NULL,
    work_process_id character varying(50) NOT NULL,
    process_order integer DEFAULT 0,
    unit_override character varying(20),
    estimated_minutes_override integer,
    created_at timestamp without time zone DEFAULT now(),
    updated_at timestamp without time zone DEFAULT now(),
    is_active boolean DEFAULT true,
    responsible_worker_id bigint,
    reporting_required boolean DEFAULT true NOT NULL,
    default_cost_category character varying(20),
    packaging_template jsonb,
    aux_alloc_method character varying(20),
    standard_yield_rate numeric(8,4),
    aux_unit_price numeric(12,4),
    aux_basis character varying(10),
    allow_semi_finished_injection boolean DEFAULT false NOT NULL,
    allow_multiple_upstream_sources boolean DEFAULT false NOT NULL,
    allow_finished_goods_source boolean DEFAULT false NOT NULL
);


--
-- Name: COLUMN product_work_processes.responsible_worker_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.responsible_worker_id IS '默认责任小组长 user_id; spawn 时作为 work_process_task.assigned_to 默认值';


--
-- Name: COLUMN product_work_processes.reporting_required; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.reporting_required IS '是否需要报工 (默认 true 逐道报). false = 该工序保留配置但 spawn 时跳过, 不生成报工任务 (六扇门中间免报场景).';


--
-- Name: COLUMN product_work_processes.default_cost_category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.default_cost_category IS '工序默认成本类别(报工继承) RAW_MATERIAL/SEASONING/AUXILIARY/PACKAGING/OTHER';


--
-- Name: COLUMN product_work_processes.packaging_template; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.packaging_template IS '工序默认包装明细模板 [{name,cost}](报工继承)';


--
-- Name: COLUMN product_work_processes.aux_alloc_method; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.aux_alloc_method IS '工序辅料分摊方式(报工继承) BY_OUTPUT/FIXED_RATIO';


--
-- Name: COLUMN product_work_processes.standard_yield_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.standard_yield_rate IS '标准出成率(配方率, 小数 0.85=85%); 投料-产出对账基准: 实际报工率 vs 标准 → 抓多投/误差。审计②: 对账两端必须一端标准一端实际, 否则恒等0无信号。';


--
-- Name: COLUMN product_work_processes.aux_unit_price; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.aux_unit_price IS '辅料标准单价(元/kg); 离线按配方算好录入, 非实时BOM; 未配=NULL 视为 0 不崩 (客户: 工序无辅料不能跑不下去)。';


--
-- Name: COLUMN product_work_processes.aux_basis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.aux_basis IS '元/kg 乘哪侧 kg: INPUT(投入侧)|OUTPUT(产出侧); 保水工序 output>input 必须显式 (审计 B-1)。';


--
-- Name: COLUMN product_work_processes.allow_semi_finished_injection; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.product_work_processes.allow_semi_finished_injection IS 'Whether this product process is a semi-finished/finished-goods injection step (张权 R4): when true, the per-process entry screen offers the SFI/FG inventory picker so production can start from mid-chain using existing stock, skipping earlier processes.';


