    target_finished_good_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT ck_production_batch_workflow_selection CHECK (((((workflow_selection_mode)::text = 'LEGACY'::text) AND (selected_workflow_id IS NULL) AND (selected_workflow_version IS NULL)) OR (((workflow_selection_mode)::text = 'WORKFLOW'::text) AND (selected_workflow_id IS NOT NULL) AND (selected_workflow_version IS NOT NULL))))
);


--
-- Name: COLUMN production_batches.custom_fields; Type: COMMENT; Schema: public; Owner: -
