--
-- Name: production_plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.production_plans (
    id character varying(191) NOT NULL,
    created_at timestamp without time zone NOT NULL,
    deleted_at timestamp without time zone,
    updated_at timestamp without time zone NOT NULL,
    actual_equipment_cost numeric(10,2),
    actual_labor_cost numeric(10,2),
    actual_material_cost numeric(10,2),
    actual_other_cost numeric(10,2),
    actual_quantity numeric(10,2),
    allocated_quantity numeric(10,2),
    created_by bigint NOT NULL,
    customer_order_number character varying(100),
    end_time timestamp without time zone,
    estimated_equipment_cost numeric(10,2),
    estimated_labor_cost numeric(10,2),
    estimated_material_cost numeric(10,2),
    estimated_other_cost numeric(10,2),
    expected_completion_date date,
    factory_id character varying(255) NOT NULL,
    is_fully_matched boolean,
    notes text,
    plan_number character varying(50) NOT NULL,
    plan_type character varying(255),
    planned_quantity numeric(10,2) NOT NULL,
    priority integer,
    product_type_id character varying(191) NOT NULL,
    start_time timestamp without time zone,
    status character varying(255) NOT NULL,
    ai_confidence integer,
    cr_value numeric(5,2),
    forecast_reason character varying(255),
    is_mixed_batch boolean,
    mixed_batch_type character varying(30),
    related_orders jsonb,
    source_customer_name character varying(100),
    source_order_id character varying(50),
    source_type character varying(30),
    current_probability numeric(5,4),
    probability_updated_at timestamp without time zone,
    approval_comment character varying(500),
    approval_status character varying(20),
    approved_at timestamp without time zone,
    approver_id bigint,
    approver_name character varying(50),
    force_insert_by bigint,
    force_insert_reason character varying(500),
    force_inserted_at timestamp without time zone,
    is_force_inserted boolean,
    requires_approval boolean,
    suggested_production_line_id character varying(36),
    estimated_workers integer,
    assigned_supervisor_id bigint,
    process_name character varying(200),
    batch_date date,
    source_order_item_id character varying(50),
    planned_date date,
    vflag character varying(20) DEFAULT 'UNCREATED'::character varying NOT NULL,
    is_locked boolean DEFAULT false NOT NULL,
    lock_reason text,
    locked_at timestamp without time zone,
    locked_by bigint,
    plan_source_type character varying(30) DEFAULT 'NORMAL'::character varying NOT NULL,
    secondary_source_wip_id bigint,
    source_order_ids jsonb DEFAULT '[]'::jsonb,
    skip_process_reporting boolean DEFAULT false NOT NULL,
    planned_unit character varying(32) NOT NULL,
    target_finished_good_ids jsonb,
    workflow_selection_mode character varying(16),
    selected_workflow_id bigint,
    selected_workflow_version integer,
    selected_bom_recipe_id character varying(191),
    selected_bom_version integer,
    planned_net_weight_grams numeric(20,6),
    source_display_quantity numeric(20,6),
    source_display_unit character varying(32),
    workflow_output_unit character varying(32),
    customer_id character varying(191),
    processing_mode character varying(32),
    material_supply_mode character varying(32),
    output_ownership character varying(32),
    client_request_id character varying(128),
    cancel_reason text,
    cancelled_by bigint,
    cancelled_at timestamp without time zone,
    selected_workflow_revision_id bigint,
    selected_workflow_revision_hash character varying(64),
    workflow_output_units_by_product jsonb DEFAULT '{}'::jsonb NOT NULL,
    selected_bom_family_id character varying(64),
    selected_bom_recipe_ids_by_product jsonb DEFAULT '{}'::jsonb NOT NULL,
    selected_bom_versions_by_product jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT chk_pp_vflag CHECK (((vflag)::text = ANY ((ARRAY['UNCREATED'::character varying, 'PENDING'::character varying, 'CREATED'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT chk_production_plan_output_ownership CHECK (((output_ownership IS NULL) OR ((output_ownership)::text = ANY ((ARRAY['COMPANY_OWNED'::character varying, 'CUSTOMER_OWNED'::character varying])::text[])))),
    CONSTRAINT chk_production_plan_processing_mode CHECK (((processing_mode IS NULL) OR ((processing_mode)::text = ANY ((ARRAY['STANDARD_SALE'::character varying, 'TOLL_PROCESSING'::character varying])::text[])))),
    CONSTRAINT chk_production_plan_supply_contract CHECK (((processing_mode IS NULL) OR (((processing_mode)::text = 'STANDARD_SALE'::text) AND ((material_supply_mode)::text = 'FACTORY_SUPPLIED'::text) AND ((output_ownership)::text = 'COMPANY_OWNED'::text)) OR (((processing_mode)::text = 'TOLL_PROCESSING'::text) AND ((material_supply_mode)::text = 'CUSTOMER_SUPPLIED'::text) AND ((output_ownership)::text = 'CUSTOMER_OWNED'::text) AND (customer_id IS NOT NULL) AND ((source_order_id IS NOT NULL) OR ((source_type)::text = 'SAFETY_STOCK'::text))))),
    CONSTRAINT chk_production_plan_supply_mode CHECK (((material_supply_mode IS NULL) OR ((material_supply_mode)::text = ANY ((ARRAY['CUSTOMER_SUPPLIED'::character varying, 'FACTORY_SUPPLIED'::character varying])::text[])))),
    CONSTRAINT chk_production_plan_supply_pair CHECK ((((processing_mode IS NULL) AND (material_supply_mode IS NULL)) OR ((processing_mode IS NOT NULL) AND (material_supply_mode IS NOT NULL)))),
    CONSTRAINT ck_production_plan_workflow_selection CHECK ((((workflow_selection_mode IS NULL) AND (selected_workflow_id IS NULL) AND (selected_workflow_version IS NULL)) OR (((workflow_selection_mode)::text = 'LEGACY'::text) AND (selected_workflow_id IS NULL) AND (selected_workflow_version IS NULL)) OR (((workflow_selection_mode)::text = 'WORKFLOW'::text) AND (selected_workflow_id IS NOT NULL) AND (selected_workflow_version IS NOT NULL))))
);


