-- Name: production_settlement_output_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.production_settlement_output_lines (
    id character varying(191) NOT NULL,
    factory_id character varying(50) NOT NULL,
    settlement_id character varying(191) NOT NULL,
    production_plan_id character varying(191) NOT NULL,
    product_type_id character varying(191) NOT NULL,
    reported_batch_number character varying(64) NOT NULL,
    reported_quantity numeric(18,4) NOT NULL,
    quantity_unit character varying(20) NOT NULL,
    bom_family_id character varying(64) NOT NULL,
    bom_recipe_id character varying(191) NOT NULL,
    bom_recipe_version integer NOT NULL,
    target_terminal_node_id character varying(128) NOT NULL,
    output_role character varying(24) NOT NULL,
    cost_allocation_ratio numeric(7,4),
    byproduct_nrv_unit_price numeric(15,4),
    allocated_cost numeric(18,6),
    unit_cost numeric(18,6),
    received_quantity numeric(18,4),
    finished_goods_batch_id character varying(191),
    receipt_idempotency_key character varying(128),
    received_by bigint,
    received_at timestamp without time zone,
    status character varying(24) DEFAULT 'REPORTED'::character varying NOT NULL,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp without time zone,
    CONSTRAINT ck_pso_output_role CHECK (((output_role)::text = ANY ((ARRAY['MAIN'::character varying, 'CO_PRODUCT'::character varying, 'BY_PRODUCT'::character varying])::text[]))),
    CONSTRAINT ck_pso_received_quantity CHECK (((received_quantity IS NULL) OR ((received_quantity > (0)::numeric) AND (received_quantity <= reported_quantity)))),
    CONSTRAINT ck_pso_reported_quantity CHECK ((reported_quantity > (0)::numeric)),
    CONSTRAINT ck_pso_status CHECK (((status)::text = ANY ((ARRAY['REPORTED'::character varying, 'PARTIALLY_RECEIVED'::character varying, 'RECEIVED'::character varying])::text[])))
);


