    variance_quantity numeric(12,2) NOT NULL,
    tolerance_quantity numeric(12,2) NOT NULL,
    quantity_unit character varying(20),
    variance_reason character varying(64) NOT NULL,
    responsibility_side character varying(30) NOT NULL,
    status character varying(30) NOT NULL,
    note text,
    created_by bigint,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    CONSTRAINT chk_prod_transit_ledger_type CHECK (((ledger_type)::text = ANY ((ARRAY['FINISHED_GOODS_RECEIPT'::character varying, 'RAW_MATERIAL_ISSUE'::character varying, 'SEMI_FINISHED_ISSUE'::character varying])::text[]))),
    CONSTRAINT chk_prod_transit_responsibility CHECK (((responsibility_side)::text = ANY ((ARRAY['PENDING'::character varying, 'PRODUCTION'::character varying, 'WAREHOUSE'::character varying, 'WEIGHING_ERROR'::character varying])::text[]))),
    CONSTRAINT chk_prod_transit_status CHECK (((status)::text = ANY ((ARRAY['OPEN'::character varying, 'RESOLVED'::character varying, 'VOIDED'::character varying])::text[])))
);


