--
-- Name: purchase_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_orders (
    id character varying(191) NOT NULL,
    factory_id character varying(191) NOT NULL,
    order_number character varying(50) NOT NULL,
    supplier_id character varying(191),
    purchase_type character varying(32) DEFAULT 'DIRECT'::character varying NOT NULL,
    order_date date NOT NULL,
    expected_delivery_date date,
    total_amount numeric(15,2) DEFAULT 0,
    tax_amount numeric(15,2) DEFAULT 0,
    status character varying(32) DEFAULT 'DRAFT'::character varying NOT NULL,
    created_by bigint NOT NULL,
    approved_by bigint,
    approved_at timestamp without time zone,
    remark text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    deleted_at timestamp without time zone,
    finance_reviewed_by bigint,
    finance_reviewed_at timestamp without time zone,
    finance_review_notes text,
    sales_order_id character varying(191),
    version bigint DEFAULT 0 NOT NULL,
    vflag character varying(20) DEFAULT 'UNCREATED'::character varying NOT NULL,
    marker_color character varying(16),
    is_imported boolean,
    inquiry_quote_id character varying(191),
    ai_invocation_metadata jsonb,
    settlement_type character varying(32),
    contract_number character varying(100),
    invoice_reminder_days integer,
    purchase_invoice_status character varying(32) DEFAULT 'NOT_RECEIVED'::character varying NOT NULL,
    receiving_close_reason_code character varying(40),
    receiving_close_notes text,
    receiving_closed_by bigint,
    receiving_closed_at timestamp without time zone,
    CONSTRAINT chk_po_vflag CHECK (((vflag)::text = ANY ((ARRAY['UNCREATED'::character varying, 'PENDING'::character varying, 'CREATED'::character varying, 'FAILED'::character varying])::text[]))),
    CONSTRAINT ck_po_status CHECK (((status)::text = ANY (ARRAY['DRAFT'::text, 'SUBMITTED'::text, 'APPROVED'::text, 'WORKFLOW_RUNNING'::text, 'PENDING_FINANCE_REVIEW'::text, 'FINANCE_APPROVED'::text, 'FINANCE_REJECTED'::text, 'PARTIAL_RECEIVED'::text, 'COMPLETED'::text, 'CANCELLED'::text, 'CLOSED'::text]))),
    CONSTRAINT ck_po_type CHECK (((purchase_type)::text = ANY (ARRAY[('DIRECT'::character varying)::text, ('HQ_UNIFIED'::character varying)::text, ('URGENT'::character varying)::text])))
);


--
-- Name: COLUMN purchase_orders.supplier_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.purchase_orders.supplier_id IS 'Nullable only while status is DRAFT; application submission validation requires a supplier';


