--

COMMENT ON COLUMN public.purchase_orders.settlement_type IS 'SP6: 结算方式(CASH/NET30/NET60/PREPAID 等)';


--
-- Name: COLUMN purchase_orders.contract_number; Type: COMMENT; Schema: public; Owner: -
