--

CREATE TABLE public.semi_finished_inventory (
    id bigint NOT NULL,
    version bigint,
    factory_id character varying(50) NOT NULL,
    batch_id bigint,
    intermediate_batch_no character varying(64) NOT NULL,
    source_work_process_task_id bigint,
    process_order integer,
    product_type_id character varying(100),
    produced_quantity numeric(12,2),
    consumed_quantity numeric(12,2),
    available_quantity numeric(12,2),
    unit character varying(16),
    status character varying(20) DEFAULT 'AVAILABLE'::character varying,
    material_batch_refs jsonb,
    created_at timestamp without time zone,
    updated_at timestamp without time zone,
    deleted_at timestamp without time zone,
    accumulated_cost numeric(14,2),
    unit_cost numeric(14,4),
    adjustment_quantity numeric(12,2) DEFAULT 0 NOT NULL,
    is_rework boolean DEFAULT false NOT NULL
);


--
-- Name: TABLE semi_finished_inventory; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.semi_finished_inventory IS 'G6 半成品库存(WIP)权威账: 每道工序产出一笔有余额存量行, 下道领用扣减, 结余留作 WIP; 防呆 :max + D3 余料退回靠本表';


--
-- Name: COLUMN semi_finished_inventory.intermediate_batch_no; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory.intermediate_batch_no IS '工序批次号(复用 Phase A 已生成, 工厂内唯一); 幂等 upsert 锚点 (跨天多次报工累加同行)';


--
-- Name: COLUMN semi_finished_inventory.available_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory.available_quantity IS '余额 = produced_quantity − consumed_quantity (G7 结余; 下道领用 :max)';


--
-- Name: COLUMN semi_finished_inventory.material_batch_refs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory.material_batch_refs IS '溯源(从产出报工继承); 格式 [{"materialBatchId":Long,"quantity":Number,"unit":String}]; 镜像 production_reports.material_batch_refs';


--
-- Name: COLUMN semi_finished_inventory.accumulated_cost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory.accumulated_cost IS '滚动累计成本(人工+材料)(元); null=无成本数据(绝不默认0)';


--
-- Name: COLUMN semi_finished_inventory.unit_cost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory.unit_cost IS '单位成本 = accumulated_cost / produced_quantity; null=无成本数据';


--
-- Name: COLUMN semi_finished_inventory.adjustment_quantity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory.adjustment_quantity IS '盘点净修正量 (可正可负); available = produced − consumed + adjustment; 盘盈/盘亏差异存于此, 不动 produced/consumed/成本';


--
-- Name: COLUMN semi_finished_inventory.is_rework; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory.is_rework IS '这一行装的是回料(不良品回投); true 时可穿过投料下拉的阶段过滤回到靠前工序。判据来自画布 data.isRework';


