--
-- Name: COLUMN semi_finished_inventory_transactions.txn_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory_transactions.txn_type IS 'IN=生产产出入库 | OUT=同单续工序领用 | SECONDARY_CONSUME=跨单二次加工领用 | REVERSE=撤回 | ADJUST=盘点调整';


--
-- Name: COLUMN semi_finished_inventory_transactions.source_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory_transactions.source_type IS 'PRODUCTION_OUTPUT/SECONDARY_CONSUME/REVERSAL/STOCKTAKE/TRANSFER_OUT';


--
