--

COMMENT ON COLUMN public.semi_finished_inventory_transactions.unit_cost_at_txn IS 'IN时=本次产出单位成本; OUT/REVERSE时=均价快照; null=成本未知';


--
-- Name: COLUMN semi_finished_inventory_transactions.balance_after; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.semi_finished_inventory_transactions.balance_after IS '写入后可用量快照(available_quantity)';


--
