--
-- Name: tool_execution_audit_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tool_execution_audit_events (
    id character varying(36) NOT NULL,
    request_fingerprint character varying(64) NOT NULL,
    correlation_fingerprint character varying(64) NOT NULL,
    trace_fingerprint character varying(64) NOT NULL,
    tenant_id character varying(50) NOT NULL,
    business_type character varying(32) NOT NULL,
    principal_type character varying(16) NOT NULL,
    principal_id character varying(100) NOT NULL,
    tool_name character varying(150) NOT NULL,
    descriptor_version character varying(64) NOT NULL,
    source character varying(32) NOT NULL,
    execution_mode character varying(16) NOT NULL,
    command_digest character varying(64),
    confirmation_fingerprint character varying(64),
    idempotency_key_hash character varying(64),
    state character varying(16) NOT NULL,
    outcome_status character varying(32),
    result_code character varying(64),
    started_at timestamp without time zone NOT NULL,
    completed_at timestamp without time zone,
    CONSTRAINT ck_tea_hash_lengths CHECK (((length((request_fingerprint)::text) = 64) AND (length((correlation_fingerprint)::text) = 64) AND (length((trace_fingerprint)::text) = 64) AND ((command_digest IS NULL) OR (length((command_digest)::text) = 64)) AND ((confirmation_fingerprint IS NULL) OR (length((confirmation_fingerprint)::text) = 64)) AND ((idempotency_key_hash IS NULL) OR (length((idempotency_key_hash)::text) = 64)))),
    CONSTRAINT ck_tea_state CHECK (((state)::text = ANY ((ARRAY['STARTED'::character varying, 'COMPLETED'::character varying])::text[])))
);


--
-- Name: tool_execution_idempotency; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tool_execution_idempotency (
    id character varying(36) NOT NULL,
    tenant_id character varying(50) NOT NULL,
    business_type character varying(32) NOT NULL,
    principal_type character varying(16) NOT NULL,
    principal_id character varying(100) NOT NULL,
    tool_name character varying(150) NOT NULL,
    descriptor_version character varying(64) NOT NULL,
    idempotency_key_hash character varying(64) NOT NULL,
    command_digest character varying(64) NOT NULL,
    confirmation_fingerprint character varying(64) NOT NULL,
    state character varying(20) NOT NULL,
    outcome_status character varying(32),
    original_audit_event_id character varying(36) NOT NULL,
    result_code character varying(64),
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    completed_at timestamp without time zone,
    CONSTRAINT ck_tei_hash_lengths CHECK (((length((idempotency_key_hash)::text) = 64) AND (length((command_digest)::text) = 64) AND (length((confirmation_fingerprint)::text) = 64))),
    CONSTRAINT ck_tei_state CHECK (((state)::text = ANY ((ARRAY['IN_PROGRESS'::character varying, 'SUCCEEDED'::character varying, 'FAILED'::character varying, 'IN_DOUBT'::character varying])::text[])))
);


