--
-- Name: v_current_recipes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_current_recipes AS
 SELECT recipes.id,
    recipes.factory_id,
    recipes.product_type_id,
    recipes.raw_material_type_id,
    recipes.standard_quantity,
    recipes.unit,
    recipes.net_yield_rate,
    recipes.is_main_ingredient,
    recipes.notes,
    recipes.is_active,
    recipes.created_by,
    recipes.created_at,
    recipes.updated_at,
    recipes.deleted_at,
    recipes.effective_from,
    recipes.effective_to
   FROM public.recipes
  WHERE ((recipes.deleted_at IS NULL) AND (recipes.is_active = true) AND ((recipes.effective_to IS NULL) OR (recipes.effective_to > now())));


--
-- Name: v_recipes_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_recipes_effective AS
 SELECT DISTINCT ON (r.factory_id, r.product_type_id, r.raw_material_type_id) r.id,
    r.factory_id,
    r.product_type_id,
    r.raw_material_type_id,
    r.standard_quantity,
    r.unit,
    r.net_yield_rate,
    r.is_main_ingredient,
    r.notes,
    r.is_active,
    r.created_by,
    r.created_at,
    r.updated_at,
    r.deleted_at,
    r.effective_from,
    r.effective_to,
    r.variant_tag,
    r.priority
   FROM public.recipes r
  WHERE ((r.deleted_at IS NULL) AND (r.is_active = true) AND ((r.effective_from IS NULL) OR (r.effective_from <= now())) AND ((r.effective_to IS NULL) OR (r.effective_to > now())))
  ORDER BY r.factory_id, r.product_type_id, r.raw_material_type_id, r.priority DESC, r.updated_at DESC;


