-- Name: voucher_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.voucher_entries (
    id character varying(191) NOT NULL,
    voucher_id character varying(191) NOT NULL,
    line_no integer NOT NULL,
    subject_code character varying(32) NOT NULL,
    subject_name character varying(100) NOT NULL,
    description character varying(500),
    debit numeric(15,2),
    credit numeric(15,2),
    cost_center character varying(100),
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    deleted_at timestamp without time zone,
    auxiliary_type character varying(16),
    auxiliary_entity_id character varying(191),
    CONSTRAINT chk_ve_auxiliary_paired CHECK ((((auxiliary_type IS NULL) AND (auxiliary_entity_id IS NULL)) OR ((auxiliary_type IS NOT NULL) AND (auxiliary_entity_id IS NOT NULL)))),
    CONSTRAINT chk_ve_auxiliary_type CHECK (((auxiliary_type IS NULL) OR ((auxiliary_type)::text = ANY ((ARRAY['CUSTOMER'::character varying, 'SUPPLIER'::character varying, 'DEPT'::character varying, 'EMPLOYEE'::character varying, 'PROJECT'::character varying, 'INVENTORY'::character varying, 'OUTSOURCER'::character varying])::text[])))),
    CONSTRAINT chk_ve_single_side CHECK ((((COALESCE(debit, (0)::numeric) > (0)::numeric) AND (COALESCE(credit, (0)::numeric) = (0)::numeric)) OR ((COALESCE(debit, (0)::numeric) = (0)::numeric) AND (COALESCE(credit, (0)::numeric) > (0)::numeric))))
);


