);


--
-- Name: workflow_task_ports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_task_ports (
    id bigint NOT NULL,
    factory_id character varying(64) NOT NULL,
    workflow_instance_id bigint NOT NULL,
    task_id bigint NOT NULL,
    workflow_port_id character varying(128) NOT NULL,
    direction character varying(8) NOT NULL,
    ordinal integer NOT NULL,
    material_node_id character varying(128) NOT NULL,
    material_kind character varying(32) NOT NULL,
    sku_id character varying(128) NOT NULL,
    unit character varying(32) NOT NULL,
    required boolean DEFAULT true NOT NULL,
    conversion_mode character varying(32),
    conversion_expression character varying(500),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp without time zone,
    unit_code character varying(32) NOT NULL,
    material_primary_unit_code character varying(32),
    conversion_ref_id character varying(36),
    conversion_version bigint,
    conversion_from_unit_code character varying(20),
    conversion_to_unit_code character varying(20),
    conversion_factor_snapshot numeric(20,8),
    port_to_primary_factor_snapshot numeric(20,8),
    net_weight_grams_snapshot numeric(20,6),
    standard_quantity numeric(20,6),
    quantity_mode character varying(24),
    selection_group_id character varying(128),
    selection_group_label character varying(255),
    selection_group_mode character varying(32),
    selection_group_min_selections integer,
    selection_group_max_selections integer,
    input_share_ratio numeric(9,4),
    CONSTRAINT ck_workflow_task_port_quantity_mode CHECK (((quantity_mode IS NULL) OR ((quantity_mode)::text = ANY ((ARRAY['AUTO_CONVERT'::character varying, 'FIXED_RATIO'::character varying])::text[])))),
    CONSTRAINT ck_workflow_task_port_selection_group_bounds CHECK ((((selection_group_id IS NULL) AND (selection_group_label IS NULL) AND (selection_group_mode IS NULL) AND (selection_group_min_selections IS NULL) AND (selection_group_max_selections IS NULL)) OR ((selection_group_id IS NOT NULL) AND (selection_group_label IS NOT NULL) AND (selection_group_mode IS NOT NULL) AND (selection_group_min_selections IS NOT NULL) AND (selection_group_max_selections IS NOT NULL) AND (selection_group_min_selections >= 0) AND (selection_group_max_selections >= selection_group_min_selections)))),
    CONSTRAINT ck_workflow_task_port_selection_group_mode CHECK (((selection_group_mode IS NULL) OR ((selection_group_mode)::text = ANY ((ARRAY['ALL_REQUIRED'::character varying, 'EXACTLY_ONE'::character varying, 'AT_LEAST_ONE'::character varying, 'OPTIONAL'::character varying])::text[])))),
    CONSTRAINT ck_workflow_task_port_standard_quantity CHECK (((standard_quantity IS NULL) OR (standard_quantity > (0)::numeric))),
    CONSTRAINT workflow_task_ports_direction_check CHECK (((direction)::text = ANY ((ARRAY['INPUT'::character varying, 'OUTPUT'::character varying])::text[])))
);


